def compute(vars):
    old_2015 = vars["v1"]
    new_2016 = vars["v2"]
    change = new_2016 - old_2015
    return {
        "value": change,
        "trace": {
            "old_2015": old_2015,
            "new_2016": new_2016,
            "change": change,
            "output_meta": {
                "currency": None,
                "scale": "million",
                "unit": "vehicles"
            }
        }
    }
